```challenge
{
  "title": "Подключи стили",
  "task": "Подключи файл `style.css` в `head` через `link`, а заголовку в блоке `<style>` задай цвет `#6b3e26`.",
  "start": "<!doctype html>\n<html lang=\"ru\">\n<head>\n  <meta charset=\"utf-8\">\n  <title>Мой сайт</title>\n</head>\n<body>\n  <h1>Мой сайт</h1>\n</body>\n</html>",
  "checks": [
    {
      "label": "`link` на `style.css` в `head`",
      "selector": "head link[rel=\"stylesheet\"][href=\"style.css\"]"
    },
    {
      "label": "В `<style>` цвет заголовка",
      "css": {
        "selector": "h1",
        "property": "color",
        "value": "#6b3e26"
      }
    }
  ],
  "solution": "<!doctype html>\n<html lang=\"ru\">\n<head>\n  <meta charset=\"utf-8\">\n  <title>Мой сайт</title>\n  <link rel=\"stylesheet\" href=\"style.css\">\n  <style>\n    h1 { color: #6b3e26; }\n  </style>\n</head>\n<body>\n  <h1>Мой сайт</h1>\n</body>\n</html>"
}
```

